//! scaas-ua `verify` against smartcontracts/vectors/ua/groups.json (UA-2c; generated by tests/groups.rs, feature vectors):
//! the registry's rules for the group kinds as `groups.rs` writes them from the spec — key data, ua, keyHash, PoP
//! message; `verifyPop` (KeyAgg + hints / DKG PoKs + Y = Σ C_i0, then the group signature) accepts every group and refuses
//! every `UAPoP` negative, key-data validation refuses every `UAKeyData` negative, `verify` against the stored vk accepts
//! every signature and refuses every verify negative; RFC 9591 E.5, the ZF DKG vector and the T-FROST rows. Default build.
use scaas_ua::verify::{dkg_transcript_ok, frost_secp256k1, verify};
use scaas_ua::*;
use serde_json::Value;

fn load() -> Value {
    let path = format!(
        "{}/../../smartcontracts/vectors/ua/groups.json",
        env!("CARGO_MANIFEST_DIR")
    );
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}
fn bytes(v: &Value) -> Vec<u8> {
    hex::decode(v.as_str().unwrap().trim_start_matches("0x")).unwrap()
}
fn b32(v: &Value) -> [u8; 32] {
    bytes(v).try_into().unwrap()
}
fn arr(v: &Value) -> &Vec<Value> {
    v.as_array().unwrap()
}
/// `(portableRecordDigest, message)` of a group key (UA-8: no chain context; typed-signing: the typed records, no PQZ key,
/// the zero KEM record).
fn pop_message(_v: &Value, kind: u16, kd: &[u8]) -> ([u8; 32], [u8; 32]) {
    let ua = ua_of(kind, kd).unwrap();
    let no_kem = ua_portable::kem_record_hash(&ua, 0, &[]).unwrap();
    let pd = ua_portable::portable_record_digest(&ua, kind, &[0; 32], &no_kem);
    (
        pd,
        ua_message(
            kind,
            &ua_portable::pop_v2_tag(),
            &ua_portable::registration_digest(&ua, kind, &[0; 32], &no_kem, &[0; 32]),
        )
        .unwrap(),
    )
}

#[test]
fn groups_register_and_sign() {
    let v = load();
    let gs = arr(&v["groups"]);
    assert_eq!(gs.len(), 20);
    for g in gs {
        let (kind, kd, name) = (
            g["kind"].as_u64().unwrap() as u16,
            bytes(&g["keyData"]),
            g["name"].as_str().unwrap(),
        );
        assert_eq!(
            derive_ua(kind, &kd, false).unwrap(),
            b32(&g["ua"]),
            "{name}"
        );
        assert_eq!(
            key_hash_of(kind, &kd).unwrap().unwrap(),
            b32(&g["keyHash"]),
            "{name}"
        );
        let vk = bytes(&g["vk"]);
        assert_eq!(
            vk,
            kd[..if matches!(kind, 0x0110 | 0x0111) {
                33
            } else {
                64
            }],
            "{name}"
        );
        let (pd, m) = pop_message(&v, kind, &kd);
        assert_eq!(
            (pd, m),
            (b32(&g["pop"]["popDigest"]), b32(&g["pop"]["message"])),
            "{name}"
        );
        assert!(
            verify(kind, &kd, &m, &bytes(&g["pop"]["blob"]), true, false),
            "{name}: verifyPop"
        );
        assert!(
            verify(kind, &vk, &m, &bytes(&g["pop"]["sig"]), false, false),
            "{name}: the PoP signature against vk"
        );
        for s in arr(&g["sigs"]) {
            let mm = ua_message(
                kind,
                &purpose_tag(s["purpose"].as_str().unwrap()).unwrap(),
                &b32(&s["digest"]),
            )
            .unwrap();
            assert_eq!(mm, b32(&s["message"]));
            assert!(
                verify(kind, &vk, &mm, &bytes(&s["sig"]), false, false),
                "{name} {}",
                s["purpose"]
            );
        }
        if matches!(kind, 0x0111 | 0x0113) {
            assert!(dkg_transcript_ok(kind, &kd), "{name}");
        }
    }
}

#[test]
fn group_negatives_refused() {
    let v = load();
    let mut n = 0;
    for g in arr(&v["groups"]) {
        let kind = g["kind"].as_u64().unwrap() as u16;
        for x in arr(&g["negatives"]) {
            let name = format!("{} {}", g["name"], x["name"]);
            if x["entry"] == "verify" {
                assert!(
                    !verify(
                        kind,
                        &bytes(&x["vk"]),
                        &b32(&x["message"]),
                        &bytes(&x["sig"]),
                        false,
                        false
                    ),
                    "{name}"
                );
            } else {
                let kd = bytes(&x["keyData"]);
                assert_eq!(ua_of(kind, &kd).unwrap(), b32(&x["ua"]), "{name}");
                let (_, m) = pop_message(&v, kind, &kd);
                assert_eq!(m, b32(&x["message"]), "{name}");
                let valid = validate_key_data(kind, &kd, false).is_ok();
                let (w, sl) = match kind {
                    0x0110 => (33, 64),
                    0x0111 => (33, 65),
                    _ => (64, 96),
                };
                let blob = bytes(&x["pop"]);
                assert_eq!(
                    verify(
                        kind,
                        &kd[..w],
                        &m,
                        &blob[..sl.min(blob.len())],
                        false,
                        false
                    ),
                    x["sigValid"].as_bool().unwrap(),
                    "{name}: sigValid"
                );
                match x["error"].as_str().unwrap() {
                    "UAKeyData" => assert!(!valid, "{name}: key data must be refused"),
                    "UAPoP" => assert!(
                        valid && !verify(kind, &kd, &m, &bytes(&x["pop"]), true, false),
                        "{name}: verifyPop must refuse"
                    ),
                    e => panic!("{name}: {e}"),
                }
            }
            n += 1;
        }
    }
    assert_eq!(n, 98); // 70 + the 28 `verify` rows of 2026-11-26 (tests/groups.rs `verify_more`)
    println!("{n} group negatives refused");
}

#[test]
fn official_sections() {
    let v = load();
    let e = &v["rfc9591E5"];
    assert!(frost_secp256k1(
        &bytes(&e["groupPublicKey"]),
        &bytes(&e["message"]),
        &bytes(&e["sig"])
    ));
    let z = &v["zfDkg"];
    assert!(dkg_transcript_ok(0x0111, &bytes(&z["keyData"])));
    // BIP-327 KeyAgg rows: Σ a_i·P_i = Σ H_i = Q, x(Q) = the official expected key
    use k256::elliptic_curve::sec1::{FromSec1Point, ToSec1Point};
    let pt = |b: &[u8]| {
        k256::ProjectivePoint::from(
            k256::AffinePoint::from_sec1_point(&k256::Sec1Point::from_bytes(b).unwrap()).unwrap(),
        )
    };
    for r in arr(&v["bip327"]["keyAgg"]) {
        let mut q = k256::ProjectivePoint::IDENTITY;
        for (i, k) in arr(&r["keys"]).iter().enumerate() {
            let a: k256::Scalar = Option::from(
                <k256::Scalar as k256::elliptic_curve::PrimeField>::from_repr(
                    b32(&r["coefficients"][i]).into(),
                ),
            )
            .unwrap();
            let h = pt(&[&[4u8][..], &bytes(&r["hints"][i])].concat());
            assert!(pt(&bytes(k)) * a == h);
            q += h;
        }
        assert_eq!(
            q.to_affine().to_sec1_point(true).as_bytes(),
            &bytes(&r["Q"])[..]
        );
        assert_eq!(bytes(&r["Q"])[1..], bytes(&r["expectedX"])[..]);
    }
}

#[test]
fn t_frost_rows() {
    let v = load();
    let rows = arr(&v["tFrost"]);
    assert_eq!(rows.len(), 10);
    for r in rows {
        let (key, msg, sig) = (bytes(&r["key"]), bytes(&r["message"]), bytes(&r["sig"]));
        let ok = match r["verifier"].as_str().unwrap() {
            "frost-secp256k1" => frost_secp256k1(&key, &msg, &sig),
            _ => {
                let (Ok(vk), Ok(s)) = (
                    k256::schnorr::VerifyingKey::from_slice(&key),
                    k256::schnorr::Signature::try_from(&sig[..]),
                ) else {
                    panic!()
                };
                vk.verify_raw(&msg, &s).is_ok()
            }
        };
        assert_eq!(ok, r["valid"].as_bool().unwrap(), "{}", r["name"]);
    }
}

/// bls-multi T4: groups.json `blsMulti` (written by tests/groups.rs): the `H_G1` KATs under both DSTs, every group's id, stored form,
/// `popMsg` and pop, every PoP row (`verifyPop`) and signature row (`verify` and `verifyMinimal`) as written.
#[test]
fn bls_multi_rows_verify() {
    use scaas_ua::bls_multi as bm;
    let v = load();
    let s = &v["blsMulti"];
    assert_eq!(
        s["dsts"]["sig"].as_str().unwrap().as_bytes(),
        &bm::DST_MULTI_SIG[..]
    );
    assert_eq!(
        s["dsts"]["pop"].as_str().unwrap().as_bytes(),
        &bm::DST_MULTI_POP[..]
    );
    for r in arr(&s["hashToG1"]) {
        let dst = if r["dst"] == "sig" {
            &bm::DST_MULTI_SIG[..]
        } else {
            &bm::DST_MULTI_POP[..]
        };
        assert_eq!(
            &bm::g1_encode(&scaas_ua::verify::hash_to_g1_bls12381(
                &bytes(&r["msg"]),
                dst
            ))[..],
            &bytes(&r["point"])[..]
        );
    }
    for g in arr(&s["groups"]) {
        let d = bytes(&g["keyData"]);
        let name = g["name"].as_str().unwrap();
        assert_eq!(
            derive_ua(0x0121, &d, false).unwrap(),
            b32(&g["ua"]),
            "{name}"
        );
        assert_eq!(bm::stored(&d).unwrap(), bytes(&g["stored"]), "{name}");
        assert_eq!(
            bm::pop_message(&d).unwrap(),
            b32(&g["popMessage"]),
            "{name}"
        );
        assert!(
            verify(
                0x0121,
                &d,
                &b32(&g["popMessage"]),
                &bytes(&g["pop"]),
                true,
                false
            ),
            "{name}"
        );
    }
    let (mut pops, mut sigs) = (0, 0);
    for r in arr(&s["pop"]) {
        let d = bytes(&r["keyData"]);
        assert_eq!(
            bm::pop_message(&d).unwrap(),
            b32(&r["popMessage"]),
            "{}",
            r["name"]
        );
        let ok = verify(
            0x0121,
            &d,
            &b32(&r["popMessage"]),
            &bytes(&r["pop"]),
            true,
            false,
        );
        assert_eq!(ok, r["valid"].as_bool().unwrap(), "{}", r["name"]);
        pops += 1;
    }
    for r in arr(&s["signatures"]) {
        let (d, m, sig) = (
            bytes(&r["keyData"]),
            b32(&r["uaMsg"]),
            bytes(&r["signature"]),
        );
        assert_eq!(
            bm::stored(&d).unwrap(),
            bytes(&r["stored"]),
            "{}",
            r["name"]
        );
        assert_eq!(
            verify(0x0121, &d, &m, &sig, false, false),
            r["verify"].as_bool().unwrap(),
            "{}",
            r["name"]
        );
        assert_eq!(
            verify(0x0121, &d, &m, &sig, false, true),
            r["minimal"].as_bool().unwrap(),
            "{}",
            r["name"]
        );
        sigs += 1;
    }
    assert_eq!((pops, sigs), (11, 30));
    // T15: the wallet members' parts aggregate to the row's signature and pop, which verify (the bindings reproduce the parts)
    let w = &s["wallet"];
    let (d, m) = (bytes(&w["keyData"]), b32(&w["uaMsg"]));
    let parts = |f: &str| -> Vec<(u8, [u8; 128])> {
        arr(&w["members"])
            .iter()
            .map(|x| {
                (
                    x["keyDataIndex"].as_u64().unwrap() as u8,
                    bytes(&x[f]).try_into().unwrap(),
                )
            })
            .collect()
    };
    let agg = bm::aggregate(&d, &m, &parts("partial"), false).unwrap();
    assert_eq!(&agg.signature[..], &bytes(&w["signature"])[..]);
    let signers: Vec<u8> = arr(&w["signers"])
        .iter()
        .map(|i| i.as_u64().unwrap() as u8)
        .collect();
    assert_eq!(agg.signers, signers);
    assert!(verify(0x0121, &d, &m, &agg.to_abi(), false, true));
    let pop = bm::aggregate_pop(&d, &parts("popPart")).unwrap();
    assert_eq!(&pop[..], &bytes(&w["pop"])[..]);
    assert!(verify(
        0x0121,
        &d,
        &b32(&w["popMessage"]),
        &pop,
        true,
        false
    ));
    assert_eq!(derive_ua(0x0121, &d, false).unwrap(), b32(&w["ua"]));
}
